            g_banditGunGripRise = -0.04f;
            g_banditGunRearGripForward = 0.16f;
            g_banditGunRearGripInboard = -0.06f;
            g_banditGunRearGripDrop = -0.18f;
            g_banditGunForeGripLateral = 0.253f;
            g_banditGunForeGripRise = -0.206f;
