        ImGui::TextDisabled("cutout only; off by default");
        ImGui::BeginDisabled(!g_impactDecalsEnabled);
        ImGui::Text("Active: %d / %d", (int)g_impactDecals.size(),
                    (int)kMaxImpactDecals);
