static std::vector<ComPtr<ID3D12Resource>> g_fireUploadHeaps;
static std::vector<ComPtr<ID3D12Resource>> g_explosionUploadHeaps;
static std::vector<ComPtr<ID3D12Resource>> g_explosionCoreUploadHeaps;
static bool                 fullLevelAssetsLoaded = false;
static bool                 emptyLevelAssetsLoaded = false;
static StaticBufferStatsDX12 levelLoadingUploadBaseline = {};
static std::future<bool> levelDestructionLoadFuture;
static bool levelDestructionLoadInFlight = false;

static uint64_t DXRDDGIHash(uint64_t hash, uint64_t value) {
    hash ^= value;
    return hash * 1099511628211ull;
}

static void DXRDDGIHashFloat(uint64_t& hash, float value) {
    uint32_t bits = 0;
    memcpy(&bits, &value, sizeof(bits));
    hash = DXRDDGIHash(hash, bits);
}

static uint64_t DXRDDGIStringHash(const std::string& value) {
    uint64_t hash = 1469598103934665603ull;
    for (unsigned char character : value)
        hash = DXRDDGIHash(hash, character);
    return hash;
}

static void AppendDXRDDGINodeTriangles(
    const std::shared_ptr<SceneNode>& node, CXMMATRIX instanceWorld,
    uint64_t entityId, uint64_t& geometryHash,
    std::vector<DXRProbeTriangle>& triangles, uint32_t& primitiveOrdinal) {
    if (!node) return;
    const XMMATRIX world = XMLoadFloat4x4(&node->globalTransform) *
                           instanceWorld;
    if (node->mesh) {
        for (const MeshPrimitive& primitive : node->mesh->primitives) {
            const uint32_t ordinal = primitiveOrdinal++;
            const size_t vertexCount = primitive.vertices.size() / 12u;
            const size_t indexCount = primitive.indices.empty()
                ? vertexCount : primitive.indices.size();
            for (size_t i = 0; i + 2 < indexCount; i += 3) {
                const uint32_t indices[3] = {
                    primitive.indices.empty() ? static_cast<uint32_t>(i) :
                                               primitive.indices[i],
                    primitive.indices.empty() ? static_cast<uint32_t>(i + 1) :
                                               primitive.indices[i + 1],
                    primitive.indices.empty() ? static_cast<uint32_t>(i + 2) :
                                               primitive.indices[i + 2]
                };
                if (indices[0] >= vertexCount || indices[1] >= vertexCount ||
                    indices[2] >= vertexCount)
                    continue;
                DXRProbeTriangle triangle;
                XMFLOAT3* points[3] = {
                    &triangle.a, &triangle.b, &triangle.c
                };
                for (uint32_t corner = 0; corner < 3; ++corner) {
                    const size_t base = static_cast<size_t>(indices[corner]) * 12u;
                    XMStoreFloat3(points[corner], XMVector3TransformCoord(
                        XMVectorSet(primitive.vertices[base],
                                    primitive.vertices[base + 1],
                                    primitive.vertices[base + 2], 1.0f), world));
                    DXRDDGIHashFloat(geometryHash, points[corner]->x);
                    DXRDDGIHashFloat(geometryHash, points[corner]->y);
                    DXRDDGIHashFloat(geometryHash, points[corner]->z);
                }
                triangle.sourceId = DXRProbeLayout::Hash64(entityId ^
                    (static_cast<uint64_t>(ordinal) << 32u) ^
                    static_cast<uint64_t>(i / 3u));
                triangles.push_back(triangle);
            }
        }
    }
    for (const auto& child : node->children)
        AppendDXRDDGINodeTriangles(child, instanceWorld, entityId,
            geometryHash, triangles, primitiveOrdinal);
}

static void AppendDXRDDGITerrain(std::vector<DXRProbeTriangle>& triangles,
                                 uint64_t& geometryHash) {
    auto params = CurrentTerrainParams();
    params.heightScale = scene.terrainHeightScale;
    const float width = params.tilesX * params.tileSize;
    const float depth = params.tilesZ * params.tileSize;
    const float step = (std::max)(2.0f,
        g_game.world.Level().dxrDDGI.surfaceSpacing);
    const uint32_t columns = static_cast<uint32_t>(std::ceil(width / step));
    const uint32_t rows = static_cast<uint32_t>(std::ceil(depth / step));
    // Grid min corner honours the tile origin offset so GI probes track an
    // edge-extended (off-center) island instead of the old centered rectangle.
    const float startX = (static_cast<float>(params.originTileX) -
        params.tilesX * 0.5f) * params.tileSize;
    const float startZ = (static_cast<float>(params.originTileZ) -
        params.tilesZ * 0.5f) * params.tileSize;
    auto point = [&](uint32_t x, uint32_t z) {
        const float px = startX + (std::min)(width, x * step);
        const float pz = startZ + (std::min)(depth, z * step);
        return XMFLOAT3(px, TerrainRendererDX12::HeightAt(params, px, pz), pz);
    };
    for (uint32_t z = 0; z < rows; ++z) {
        for (uint32_t x = 0; x < columns; ++x) {
            const XMFLOAT3 p00 = point(x, z);
            const XMFLOAT3 p10 = point(x + 1, z);
            const XMFLOAT3 p01 = point(x, z + 1);
            const XMFLOAT3 p11 = point(x + 1, z + 1);
            DXRProbeTriangle pair[2] = {
                { p00, p01, p10, DXRProbeLayout::Hash64(
                    0x5445525241494eull ^ (static_cast<uint64_t>(z) << 32u) ^ x) },
                { p10, p01, p11, DXRProbeLayout::Hash64(
                    0x5445525241494eull ^ (static_cast<uint64_t>(z) << 32u) ^ x ^
                    0x80000000ull) }
            };
            for (const DXRProbeTriangle& triangle : pair) {
                const XMFLOAT3 points[3] = {
                    triangle.a, triangle.b, triangle.c
                };
                for (const XMFLOAT3& p : points) {
                    DXRDDGIHashFloat(geometryHash, p.x);
                    DXRDDGIHashFloat(geometryHash, p.y);
                    DXRDDGIHashFloat(geometryHash, p.z);
                }
                triangles.push_back(triangle);
            }
        }
    }
}

static void BuildDXRDDGINodeScene(
    const std::shared_ptr<SceneNode>& node, uint64_t meshNamespace,
    const std::vector<XMMATRIX>& worlds, const std::vector<uint64_t>& entityIds,
    uint32_t& nodeOrdinal, ID3D12GraphicsCommandList4* commandList,
    std::vector<DXRScene::Instance>& instances) {
    if (!node) return;
    const uint32_t ordinal = nodeOrdinal++;
    if (node->mesh) {
        std::vector<DXRScene::Geometry> geometries;
        uint64_t sourceHash = 1469598103934665603ull;
        for (const MeshPrimitive& primitive : node->mesh->primitives) {
            if (!primitive.vertexBuffer || primitive.vertices.size() < 36)
                continue;
            DXRScene::Geometry geometry;
            geometry.vertexAddress =
                primitive.vertexBuffer->GetGPUVirtualAddress();
            geometry.vertexCount =
                static_cast<uint32_t>(primitive.vertices.size() / 12u);
            geometry.vertexStride = 12u * sizeof(float);
            geometry.indexAddress = primitive.indexBuffer
                ? primitive.indexBuffer->GetGPUVirtualAddress() : 0;
            geometry.indexCount = primitive.indexCount;
            geometry.indexFormat = primitive.ibv.Format;
            geometry.opaque = !primitive.material ||
                              !primitive.material->alphaCutout;
            // Snapshot the material into the hit record so the DXR closest-hit
            // shader shades with the real base colour instead of a constant.
            if (primitive.material) {
                geometry.baseColor[0] = primitive.material->baseColorFactor.x;
                geometry.baseColor[1] = primitive.material->baseColorFactor.y;
                geometry.baseColor[2] = primitive.material->baseColorFactor.z;
                geometry.baseColor[3] = primitive.material->baseColorFactor.w;
                geometry.metallic = primitive.material->metallicFactor;
                geometry.roughness = primitive.material->roughnessFactor;
            }
            // Bind this geometry to the visibility buffer's persistent copy of
            // the same mesh, so the inline RayQuery path can shade a hit from
            // the real triangle instead of approximating it with sky.
            //
            // Read rather than register: this runs during an acceleration
            // rebuild, which is not a frame, and RegisterPrimitive would upload
            // geometry outside the renderer's own ordering. A primitive the
            // rasterizer has not drawn yet simply stays invalid until the next
            // rebuild picks it up -- those rays keep today's approximation.
            UINT vbVertexOffset = 0, vbIndexOffset = 0, vbHasIndices = 0;
            if (visBuffer.MeshGeometryBinding(primitive.visibilityMeshID,
                    vbVertexOffset, vbIndexOffset, vbHasIndices)) {
                geometry.vbVertexOffset = vbVertexOffset;
                geometry.vbIndexOffset = vbIndexOffset;
                geometry.vbHasIndices = vbHasIndices;
                geometry.vbMeshValid = true;
                if (primitive.material) {
                    UINT materialID = 0;
                    UINT bindlessMaterialID = 0;
                    visBuffer.RegisterRaytracingMaterial(
                        primitive.material.get(), materialID,
                        bindlessMaterialID);
                    geometry.vbMaterialID = materialID;
                    geometry.vbBindlessMaterialID = bindlessMaterialID;
                }
            }
            geometries.push_back(geometry);
            sourceHash = DXRDDGIHash(sourceHash, geometry.vertexCount);
            sourceHash = DXRDDGIHash(sourceHash, geometry.indexCount);
            for (float component : primitive.vertices)
                DXRDDGIHashFloat(sourceHash, component);
            for (uint32_t index : primitive.indices)
                sourceHash = DXRDDGIHash(sourceHash, index);
        }
        if (!geometries.empty()) {
            const uint64_t meshId = DXRProbeLayout::Hash64(
                meshNamespace ^ ordinal);
            if (g_dxrDDGI.Scene().BuildMeshBLAS(commandList, meshId,
                                                sourceHash, geometries)) {
                const XMMATRIX nodeWorld =
                    XMLoadFloat4x4(&node->globalTransform);
                for (size_t i = 0; i < worlds.size(); ++i) {
                    DXRScene::Instance instance;
                    instance.meshId = meshId;
                    instance.entityId = i < entityIds.size() ? entityIds[i] : i;
                    XMStoreFloat4x4(&instance.transform,
                                    nodeWorld * worlds[i]);
                    instances.push_back(instance);
                }
            }
        }
    }
    for (const auto& child : node->children)
        BuildDXRDDGINodeScene(child, meshNamespace, worlds, entityIds,
            nodeOrdinal, commandList, instances);
}

// Transform-only counterpart to BuildDXRDDGINodeScene, for the per-frame TLAS
// refit.
//
// This MUST visit nodes and instances in exactly the order the build did, since
// the refit matches transforms to instance descriptors positionally. The two
// traversals are therefore kept structurally identical: same recursion order,
// same `worlds` loop, same skip conditions. The one condition that cannot be
// mirrored is `BuildMeshBLAS` succeeding -- so instead of re-testing it, this
// checks that a BLAS for the mesh id already exists, which is exactly what a
// successful build left behind.
//
// If the two ever diverge the refit is rejected on a count mismatch rather than
// silently shuffling transforms between instances, which is why the caller
// treats a false return as "fall back to the static TLAS" and not as an error.
static void GatherDXRDDGINodeTransforms(
    const std::shared_ptr<SceneNode>& node, uint64_t meshNamespace,
    const std::vector<XMMATRIX>& worlds, uint32_t& nodeOrdinal,
    std::vector<XMFLOAT4X4>& transforms) {
    if (!node) return;
    const uint32_t ordinal = nodeOrdinal++;
    if (node->mesh) {
        // Mirrors the build's "did any primitive qualify" test. A mesh whose
        // primitives were all skipped produced no BLAS and therefore no
        // instances, so it must contribute none here either.
        bool anyGeometry = false;
        for (const MeshPrimitive& primitive : node->mesh->primitives) {
            if (!primitive.vertexBuffer || primitive.vertices.size() < 36)
                continue;
            anyGeometry = true;
            break;
        }
        if (anyGeometry) {
            const uint64_t meshId = DXRProbeLayout::Hash64(
                meshNamespace ^ ordinal);
            if (g_dxrDDGI.Scene().HasMesh(meshId)) {
                const XMMATRIX nodeWorld =
                    XMLoadFloat4x4(&node->globalTransform);
                for (size_t i = 0; i < worlds.size(); ++i) {
                    XMFLOAT4X4 matrix;
                    XMStoreFloat4x4(&matrix, nodeWorld * worlds[i]);
                    transforms.push_back(matrix);
                }
            }
        }
    }
    for (const auto& child : node->children)
        GatherDXRDDGINodeTransforms(child, meshNamespace, worlds, nodeOrdinal,
                                    transforms);
}

// Per-frame TLAS transform refit. Cheap enough to run unconditionally: it walks
// the prefab batches, rebuilds the instance transform list, and issues a
// PERFORM_UPDATE over the existing acceleration structure. No BLAS work, no
// shader-table rewrite, no GPU stall.
//
// Returns false when the gathered list does not match the built instance count
// -- geometry was added or removed since the build, which needs the full
// rebuild path. The caller keeps tracing the previous structure in that case,
// which is stale but valid.
static bool RefitDXRDDGIAccelerationScene() {
    ComPtr<ID3D12GraphicsCommandList4> commandList;
    if (!g_dxrDDGI.Scene().Supported() ||
        g_dxrDDGI.Scene().RefitInstanceCount() == 0 ||
        FAILED(g_dx12.commandList.As(&commandList)))
        return false;

    std::vector<XMFLOAT4X4> transforms;
    transforms.reserve(g_dxrDDGI.Scene().RefitInstanceCount());
    for (const PrefabRenderBatch& batch : g_prefabRenderBatches) {
        uint32_t nodeOrdinal = 0;
        GatherDXRDDGINodeTransforms(batch.baseModel,
            DXRDDGIStringHash(batch.prefabId), batch.baseTransforms,
            nodeOrdinal, transforms);
    }
    if (wallModel && !g_ddgiCornellTestMode) {
        uint32_t nodeOrdinal = 0;
        const std::vector<XMMATRIX> worlds{ XMMatrixIdentity() };
        GatherDXRDDGINodeTransforms(wallModel, 0x484f555345ull, worlds,
            nodeOrdinal, transforms);
    }
    // Terrain is the last instance the build appends, and it never moves -- but
    // its identity transform still has to be re-emitted so the positional match
    // with the descriptor list holds through to the end of the list.
    //
    // Mirrors the build's own condition rather than inferring terrain's presence
    // from a count difference: an off-by-one from any other cause would look
    // identical to "terrain is missing" and would silently shift every
    // transform by one instance.
    if (scene.useMeshTerrain && g_terrain.supported && !g_ddgiCornellTestMode &&
        g_dxrDDGI.Scene().HasMesh(DXRScene::TerrainMeshId())) {
        XMFLOAT4X4 identity;
        XMStoreFloat4x4(&identity, XMMatrixIdentity());
        transforms.push_back(identity);
    }

    return g_dxrDDGI.Scene().RefitTLAS(commandList.Get(), transforms,
                                       g_dx12.frameIndex);
}

static bool BuildDXRDDGIAccelerationScene() {
    ComPtr<ID3D12GraphicsCommandList4> commandList;
    if (!g_dxrDDGI.Scene().Supported() ||
        FAILED(g_dx12.commandList.As(&commandList)))
        return false;
    // BLAS/TLAS resources and the persistently-mapped shader table are
    // replaced below. Any still-in-flight frame may be tracing against the
    // old ones (DispatchRays or the enhanced RayQuery resolve), so drain all
    // frame slots before touching any of it. Rare event; the sync is cheap
    // relative to a scene rebuild.
    WaitForGPUAllFrames();
    std::vector<DXRScene::Instance> instances;
    for (const PrefabRenderBatch& batch : g_prefabRenderBatches) {
        uint32_t nodeOrdinal = 0;
        BuildDXRDDGINodeScene(batch.baseModel,
            DXRDDGIStringHash(batch.prefabId), batch.baseTransforms,
            batch.entityIds, nodeOrdinal, commandList.Get(), instances);
    }
    if (wallModel && !g_ddgiCornellTestMode) {
        uint32_t nodeOrdinal = 0;
        const std::vector<XMMATRIX> worlds{ XMMatrixIdentity() };
        const std::vector<uint64_t> ids{ 0x484f555345ull };
        BuildDXRDDGINodeScene(wallModel, 0x484f555345ull, worlds, ids,
            nodeOrdinal, commandList.Get(), instances);
    }
    if (scene.useMeshTerrain && g_terrain.supported &&
        !g_ddgiCornellTestMode) {
        auto params = CurrentTerrainParams();
        params.heightScale = scene.terrainHeightScale;
        const float width = params.tilesX * params.tileSize;
        const float depth = params.tilesZ * params.tileSize;
        const float step = (std::max)(2.0f,
            g_game.world.Level().dxrDDGI.surfaceSpacing);
        const uint32_t columns =
            static_cast<uint32_t>(std::ceil(width / step));
        const uint32_t rows =
            static_cast<uint32_t>(std::ceil(depth / step));
        std::vector<XMFLOAT3> vertices;
        std::vector<uint32_t> indices;
        vertices.reserve((columns + 1u) * (rows + 1u));
        uint64_t terrainHash = 1469598103934665603ull;
        const float terrainStartX = (static_cast<float>(params.originTileX) -
            params.tilesX * 0.5f) * params.tileSize;
        const float terrainStartZ = (static_cast<float>(params.originTileZ) -
            params.tilesZ * 0.5f) * params.tileSize;
        for (uint32_t z = 0; z <= rows; ++z) {
            for (uint32_t x = 0; x <= columns; ++x) {
                const float px = terrainStartX +
                    (std::min)(width, x * step);
                const float pz = terrainStartZ +
                    (std::min)(depth, z * step);
                XMFLOAT3 vertex(
                    px, TerrainRendererDX12::HeightAt(params, px, pz), pz);
                vertices.push_back(vertex);
                DXRDDGIHashFloat(terrainHash, vertex.x);
                DXRDDGIHashFloat(terrainHash, vertex.y);
                DXRDDGIHashFloat(terrainHash, vertex.z);
            }
        }
        indices.reserve(columns * rows * 6u);
        for (uint32_t z = 0; z < rows; ++z) {
            for (uint32_t x = 0; x < columns; ++x) {
                const uint32_t a = z * (columns + 1u) + x;
                const uint32_t b = a + 1u;
                const uint32_t c = a + columns + 1u;
                const uint32_t d = c + 1u;
                indices.insert(indices.end(), { a, c, b, b, c, d });
            }
        }
        if (g_dxrDDGI.Scene().BuildTerrainBLAS(
                commandList.Get(), terrainHash, vertices, indices)) {
            DXRScene::Instance terrain;
            terrain.meshId = DXRScene::TerrainMeshId();
            terrain.entityId = 0;
            XMStoreFloat4x4(&terrain.transform, XMMatrixIdentity());
            instances.push_back(terrain);
        }
    }
    const bool updated = g_dxrDDGI.UpdateTLAS(commandList.Get(), instances);
    // Publish the per-geometry hit bindings the TLAS build just produced, so
    // the inline RayQuery path can shade a hit from the real triangle. Safe to
    // write in place here: WaitForGPUAllFrames above drained every frame slot.
    if (updated)
        visBuffer.UploadHitGeometry(g_dxrDDGI.Scene().HitGeometry());
    return updated;
}

static bool RebuildDXRDDGIProbeLayout(bool force) {
    g_dxrDDGI.ApplySettings(g_game.world.Level().dxrDDGI);
    scene.giMaxDistance = g_game.world.Level().dxrDDGI.maxRayDistance;
    if (!g_game.world.Level().dxrDDGI.enabled) return false;
    if (!force && !g_dxrDDGI.LayoutDirty()) return true;
    // Placed after the early-outs so the scope only covers a real rebuild; the
    // no-op calls that return above would otherwise flood the sample with 0 ms.
    ProfilerDX12::CpuScope probeLayoutProfile(g_profiler, "Editor/DXRProbeLayout");
    // Probe/atlas buffers may still be referenced by an older in-flight frame.
    // Drain EVERY frame slot, not just the current one: the DXR shader table
    // is persistently mapped and rewritten by the scene build below, so any
    // still-running DispatchRays from a previous slot would read it mid-write
    // (this crashed the live DDGI toggle).
    WaitForGPUAllFrames();
    g_dxrDDGI.ReleaseCompletedUploads();
    std::vector<DXRProbeTriangle> triangles;
    uint64_t geometryHash = 1469598103934665603ull;
    for (const PrefabRenderBatch& batch : g_prefabRenderBatches) {
        for (size_t i = 0; i < batch.baseTransforms.size(); ++i) {
            const uint64_t entityId = i < batch.entityIds.size()
                ? batch.entityIds[i]
                : DXRProbeLayout::Hash64(DXRDDGIStringHash(batch.prefabId) ^ i);
            uint32_t primitiveOrdinal = 0;
            AppendDXRDDGINodeTriangles(batch.baseModel, batch.baseTransforms[i],
                entityId, geometryHash, triangles, primitiveOrdinal);
        }
    }
    if (wallModel && !g_ddgiCornellTestMode) {
        uint32_t primitiveOrdinal = 0;
        AppendDXRDDGINodeTriangles(wallModel, XMMatrixIdentity(),
            0x484f555345ull, geometryHash, triangles, primitiveOrdinal);
    }
    if (scene.useMeshTerrain && g_terrain.supported &&
        !g_ddgiCornellTestMode)
        AppendDXRDDGITerrain(triangles, geometryHash);
    const std::filesystem::path cache = std::filesystem::path("Content/Levels") /
        ".ddgi" / (std::to_string(geometryHash) + ".ddgi");
    if (!g_dxrDDGI.BuildProbeLayout(triangles, geometryHash, cache)) {
        std::cerr << "[DDGI] BuildProbeLayout failed (triangles="
                  << triangles.size() << ")" << std::endl;
        return false;
    }
    if (!g_dxrDDGI.UploadProbeBuffers(g_dx12.commandList.Get())) {
        std::cerr << "[DDGI] UploadProbeBuffers failed" << std::endl;
        return false;
    }
    g_dxrDDGIProbeResource = g_dxrDDGI.ProbeBuffer();
    g_dxrDDGICellResource = g_dxrDDGI.CellBuffer();
    g_dxrDDGIIndexResource = g_dxrDDGI.IndexBuffer();
    g_dxrDDGIProbeCount =
        static_cast<UINT>(g_dxrDDGI.Layout().probes.size());
    g_dxrDDGICellCount =
        static_cast<UINT>(g_dxrDDGI.Layout().cells.size());
    g_dxrDDGIIndexCount =
        static_cast<UINT>(g_dxrDDGI.Layout().cellProbeIndices.size());
    g_dxrDDGICellSize = g_dxrDDGI.Layout().cellSize;
    g_ddgiIrradianceResource = g_dxrDDGI.IrradianceAtlas();
    g_ddgiVisibilityResource = g_dxrDDGI.VisibilityAtlas();
    visBuffer.UpdateDDGIResources(
        g_ddgiIrradianceResource, g_ddgiVisibilityResource);
    visBuffer.UpdateSparseDDGIResources(
        g_dxrDDGIProbeResource, g_dxrDDGIProbeCount,
        g_dxrDDGICellResource, g_dxrDDGICellCount,
        g_dxrDDGIIndexResource, g_dxrDDGIIndexCount);
    BuildDXRDDGIAccelerationScene();
    g_dxrDDGI.ResetHistory();
    return true;
}

static void DrawDXRDDGIProbeDebug(CXMMATRIX view, CXMMATRIX projection) {
    if (!g_game.world.Level().dxrDDGI.showProbes && !scene.showProbes) return;
    const auto& probes = g_dxrDDGI.GetDebugProbes();
    if (probes.empty()) return;
    const XMMATRIX viewProjection = view * projection;
    const ImVec2 display = ImGui::GetIO().DisplaySize;
    ImDrawList* draw = ImGui::GetForegroundDrawList();
    for (const DXRProbeRecord& probe : probes) {
        const XMVECTOR clip = XMVector3Transform(
            XMLoadFloat3(&probe.position), viewProjection);
        const float w = XMVectorGetW(clip);
        if (w <= 0.01f) continue;
        const float x = (XMVectorGetX(clip) / w * 0.5f + 0.5f) * display.x;
        const float y = (1.0f - (XMVectorGetY(clip) / w * 0.5f + 0.5f)) *
                        display.y;
        const ImU32 color = probe.state == DXRProbeState::Valid
            ? IM_COL32(70, 235, 100, 220)
            : (probe.state == DXRProbeState::Rejected
                ? IM_COL32(245, 65, 55, 220)
                : IM_COL32(245, 180, 45, 220));
        draw->AddCircleFilled(ImVec2(x, y), 3.5f, color);
        draw->AddCircle(ImVec2(x, y), 5.0f, IM_COL32(0, 0, 0, 180));
    }
}

// Exfil marker. The escape boat sits 62 m offshore, well past the point where
// a small hull reads against open water, so without a marker it is a win
// condition the player cannot find. Drawn only once boarding would actually
// work, so it never promises an exit that is still gated on the objective.
static void DrawEscapeBoatMarker(CXMMATRIX view, CXMMATRIX projection) {
    const VehicleSystem& vehicles = g_game.vehicles;
    if (!vehicles.EscapeBoatReady()) return;
    if (g_game.session.Screen() != GameScreen::Level1) return;
    if (g_emptyLevelMode || !g_game.session.TimerRunning()) return;
    // Same gate the boarding test uses, so the marker and the trigger agree.
    const bool objectiveMet = g_game.mission.Stats().commTowersTotal == 0 ||
                              g_game.mission.CommTowerObjectiveComplete();
    if (!objectiveMet) return;

    const XMFLOAT3 anchor{ vehicles.escapeBoatPosition.x,
                           vehicles.escapeBoatPosition.y + 3.4f,
                           vehicles.escapeBoatPosition.z };
    const XMVECTOR clip = XMVector3Transform(
        XMLoadFloat3(&anchor), view * projection);
    const float w = XMVectorGetW(clip);
    if (w <= 0.01f) return;   // behind the camera

    const ImVec2 display = ImGui::GetIO().DisplaySize;
    const ImVec2 screen{
        (XMVectorGetX(clip) / w * 0.5f + 0.5f) * display.x,
        (1.0f - (XMVectorGetY(clip) / w * 0.5f + 0.5f)) * display.y };

    const float dx = scene.camera.Position.x - vehicles.escapeBoatPosition.x;
    const float dz = scene.camera.Position.z - vehicles.escapeBoatPosition.z;
    const float distance = std::sqrt(dx * dx + dz * dz);

    ImDrawList* draw = ImGui::GetForegroundDrawList();
    const ImU32 green = IM_COL32(70, 235, 120, 235);
    draw->AddCircle(screen, 13.0f, green, 0, 2.5f);
    draw->AddCircleFilled(screen, 4.0f, green);
    char label[64];
    std::snprintf(label, sizeof(label), "EXFIL  %.0f m", distance);
    const ImVec2 size = ImGui::CalcTextSize(label);
    // Dark plate behind the text: it is read against open water and sky.
    draw->AddRectFilled(
        ImVec2(screen.x - size.x * 0.5f - 4.0f, screen.y + 17.0f),
        ImVec2(screen.x + size.x * 0.5f + 4.0f, screen.y + 21.0f + size.y),
        IM_COL32(6, 18, 12, 170), 3.0f);
    draw->AddText(ImVec2(screen.x - size.x * 0.5f, screen.y + 19.0f),
                  green, label);
}

// Friendly marker. Marines wear the same fatigues as the bandits they are
// fighting, so at a glance in tall grass there is nothing to tell them apart.
// A small dot over the head is enough: it reads instantly without covering the
// body the player is trying to shoot past.
static void DrawMarineFriendlyMarkers(CXMMATRIX view, CXMMATRIX projection) {
    if (g_bandits.empty()) return;
    if (g_game.session.Screen() != GameScreen::Level1) return;
    const XMMATRIX viewProjection = view * projection;
    const ImVec2 display = ImGui::GetIO().DisplaySize;
    ImDrawList* draw = ImGui::GetForegroundDrawList();
    for (const auto& marine : g_bandits) {
        if (!marine || marine->faction != Faction::Marine) continue;
        // Dead allies are no longer a friendly-fire hazard, and a dot hovering
        // over a corpse just clutters the fight.
        if (marine->Dead() || !marine->visible) continue;
        // Just clear of the head: the gun sits at footOffset + 1.48, so this is
        // roughly a head-height above that.
        const XMFLOAT3 anchor{ marine->position.x,
                               marine->position.y + marine->footOffset + 2.05f,
                               marine->position.z };
        const XMVECTOR clip = XMVector3Transform(
            XMLoadFloat3(&anchor), viewProjection);
        const float w = XMVectorGetW(clip);
        if (w <= 0.01f) continue;   // behind the camera
        const ImVec2 screen{
            (XMVectorGetX(clip) / w * 0.5f + 0.5f) * display.x,
            (1.0f - (XMVectorGetY(clip) / w * 0.5f + 0.5f)) * display.y };
        // Shrink with distance so a squad far off does not read as a row of
        // big blobs, with a floor so it never disappears entirely.
        const float dx = marine->position.x - scene.camera.Position.x;
        const float dy = marine->position.y - scene.camera.Position.y;
        const float dz = marine->position.z - scene.camera.Position.z;
        const float distance = std::sqrt(dx * dx + dy * dy + dz * dz);
        const float radius = (std::max)(2.0f, 5.0f - distance * 0.03f);

        // Friendly blue, with a hard dark edge under everything: what makes a
        // marker read as bright is the contrast beneath it, not the fill.
        const ImU32 tint    = IM_COL32(120, 195, 255, 255);
        const ImU32 shadow  = IM_COL32(0, 0, 0, 235);

        // Nameplate: callsign on top, range under it, dot below both -- the
        // dot stays on the anchor so it still points at the head.
        char range[24];
        std::snprintf(range, sizeof(range), "%.0f m", distance);
        const ImVec2 nameSize = ImGui::CalcTextSize(marine->callsign.c_str());
        const ImVec2 rangeSize = ImGui::CalcTextSize(range);

        const float nameY = screen.y - radius - 34.0f;
        const float rangeY = nameY + nameSize.y + 1.0f;
        const ImVec2 namePos(screen.x - nameSize.x * 0.5f, nameY);
        const ImVec2 rangePos(screen.x - rangeSize.x * 0.5f, rangeY);

        // Offset drop shadow rather than an outline pass: one extra draw per
        // string, and enough to hold the text against sky or grass.
        draw->AddText(ImVec2(namePos.x + 1.0f, namePos.y + 1.0f), shadow,
                      marine->callsign.c_str());
        draw->AddText(namePos, tint, marine->callsign.c_str());
        draw->AddText(ImVec2(rangePos.x + 1.0f, rangePos.y + 1.0f), shadow,
                      range);
        draw->AddText(rangePos, tint, range);

        // Downward triangle pointing at the head. Drawn twice: an outset black
        // copy first as the hard edge, then the blue on top.
        const float half = radius + 1.6f;          // half-width at the top edge
        const float drop = (radius + 1.6f) * 1.7f; // apex below that edge
        const auto triangle = [&](float grow, ImU32 colour) {
            draw->AddTriangleFilled(
                ImVec2(screen.x - half - grow, screen.y - drop * 0.5f - grow),
                ImVec2(screen.x + half + grow, screen.y - drop * 0.5f - grow),
                ImVec2(screen.x, screen.y + drop * 0.5f + grow),
                colour);
        };
        triangle(2.0f, IM_COL32(0, 0, 0, 255));
        triangle(0.0f, tint);
    }
}

// Debug overlay for impact decals. They are a per-pixel volume test with no
// geometry, so a mark that lands on the wrong face or the wrong size leaves
// nothing to inspect in a capture. This draws what the shader is testing:
// the disc in its own surface plane, the normal it was projected along, and
// the depth band either side of that plane.
static void DrawImpactDecalDebug(CXMMATRIX view, CXMMATRIX projection) {
    if (!g_showDecalDebug || g_impactDecals.empty()) return;
    const XMMATRIX viewProjection = view * projection;
    const ImVec2 display = ImGui::GetIO().DisplaySize;
    ImDrawList* draw = ImGui::GetForegroundDrawList();
    auto project = [&](const XMFLOAT3& world, ImVec2& out) -> bool {
        const XMVECTOR clip =
            XMVector3Transform(XMLoadFloat3(&world), viewProjection);
        const float w = XMVectorGetW(clip);
        if (w <= 0.01f) return false;
        out.x = (XMVectorGetX(clip) / w * 0.5f + 0.5f) * display.x;
        out.y = (1.0f - (XMVectorGetY(clip) / w * 0.5f + 0.5f)) * display.y;
        return true;
    };

    int index = 0;
    for (const ImpactDecal& decal : g_impactDecals) {
        const float life = decal.age / kImpactDecalLifetime;
        const float strength = life < 0.75f
            ? 1.0f : 1.0f - (life - 0.75f) / 0.25f;
        // Green while at full strength, amber once it starts fading out, so a
        // mark that vanished early is distinguishable from one that never
        // spawned.
        const ImU32 colour = strength > 0.999f
            ? IM_COL32(90, 230, 120, 220)
            : IM_COL32(245, 190, 60, 220);

        const XMVECTOR n = XMLoadFloat3(&decal.normal);
        // Any vector not parallel to the normal gives a basis for the disc.
        XMVECTOR reference = XMVectorSet(0.0f, 1.0f, 0.0f, 0.0f);
        if (std::fabs(decal.normal.y) > 0.9f)
            reference = XMVectorSet(1.0f, 0.0f, 0.0f, 0.0f);
        const XMVECTOR tangent =
            XMVector3Normalize(XMVector3Cross(reference, n));
        const XMVECTOR bitangent = XMVector3Cross(n, tangent);

        // The disc itself, drawn in the surface plane rather than as a screen
        // circle: a screen circle would hide exactly the orientation bugs this
        // is meant to expose.
        constexpr int kSegments = 20;
        ImVec2 previous;
        bool havePrevious = false;
        bool anyVisible = false;
        for (int i = 0; i <= kSegments; ++i) {
            const float angle = (float)i / kSegments * XM_2PI;
            const XMVECTOR offset = tangent * (std::cos(angle) * decal.radius) +
                                    bitangent * (std::sin(angle) * decal.radius);
            XMFLOAT3 point;
            XMStoreFloat3(&point, XMLoadFloat3(&decal.position) + offset);
            ImVec2 screen;
            if (!project(point, screen)) { havePrevious = false; continue; }
            if (havePrevious) draw->AddLine(previous, screen, colour, 1.5f);
            previous = screen;
            havePrevious = true;
            anyVisible = true;
        }
        if (!anyVisible) { ++index; continue; }

        // Normal, at the same 0.6 * radius the shader uses for its depth band,
        // so the line length shows the volume a pixel has to fall inside.
        const float band = decal.radius * 0.6f;
        XMFLOAT3 tip;
        XMStoreFloat3(&tip, XMLoadFloat3(&decal.position) + n * band);
        ImVec2 centreScreen, tipScreen;
        if (project(decal.position, centreScreen) && project(tip, tipScreen)) {
            draw->AddLine(centreScreen, tipScreen,
                          IM_COL32(120, 195, 255, 235), 2.0f);
            draw->AddCircleFilled(tipScreen, 3.0f, IM_COL32(120, 195, 255, 235));
            char label[48];
            std::snprintf(label, sizeof(label), "%d  r%.3f  s%.2f",
                          index, decal.radius, strength);
            draw->AddText(ImVec2(centreScreen.x + 6.0f, centreScreen.y - 6.0f),
                          colour, label);
        }
        ++index;
    }
}

// Debug overlay: each enemy's vision cone (facing direction, FOV, range),
// color-coded by awareness state so patrol/alert/combat is readable at a
// glance. Projects the cone edges and arc into screen space the same way
// DrawDXRDDGIProbeDebug projects probe markers.
static void DrawEnemyVisionCones(CXMMATRIX view, CXMMATRIX projection) {
    if (!g_showEnemyVisionCones || g_bandits.empty()) return;
    const XMMATRIX viewProjection = view * projection;
    const ImVec2 display = ImGui::GetIO().DisplaySize;
    ImDrawList* draw = ImGui::GetForegroundDrawList();
    auto project = [&](const XMFLOAT3& world, ImVec2& out) -> bool {
        const XMVECTOR clip = XMVector3Transform(XMLoadFloat3(&world), viewProjection);
        const float w = XMVectorGetW(clip);
        if (w <= 0.01f) return false;
        out.x = (XMVectorGetX(clip) / w * 0.5f + 0.5f) * display.x;
        out.y = (1.0f - (XMVectorGetY(clip) / w * 0.5f + 0.5f)) * display.y;
        return true;
    };
    for (const auto& bandit : g_bandits) {
        if (!bandit || bandit->Dead() || bandit->turretGunner) continue;
        const ImU32 color = bandit->Awareness() == SkinnedEnemy::AwarenessState::Combat
            ? IM_COL32(235, 60, 55, 200)
            : (bandit->Awareness() == SkinnedEnemy::AwarenessState::Alert
                ? IM_COL32(245, 190, 40, 200)
                : IM_COL32(80, 210, 110, 170));
        const float range = bandit->VisionRange();
        const float halfFov = bandit->VisionHalfFovRadians();
        const XMFLOAT3 apex{ bandit->position.x,
                             bandit->position.y + bandit->footOffset + 1.5f,
                             bandit->position.z };
        constexpr int kArcSegments = 16;
        ImVec2 apexScreen;
        if (!project(apex, apexScreen)) continue;
        ImVec2 previous;
        bool havePrevious = false;
        for (int i = 0; i <= kArcSegments; ++i) {
            const float t = (float)i / (float)kArcSegments;
            const float angle = bandit->yaw - halfFov + t * (2.0f * halfFov);
            const XMFLOAT3 rim{ apex.x + std::sin(angle) * range,
                                apex.y,
                                apex.z + std::cos(angle) * range };
            ImVec2 rimScreen;
            if (!project(rim, rimScreen)) { havePrevious = false; continue; }
            if (i == 0 || i == kArcSegments)
                draw->AddLine(apexScreen, rimScreen, color, 1.5f);
            if (havePrevious) draw->AddLine(previous, rimScreen, color, 1.5f);
            previous = rimScreen;
            havePrevious = true;
        }
    }
}

// Rail lasers and the existing IR/NVG designator share the same world-space
// cast. The attachment is visible red; the equipment designator remains white
// and only appears through the goggle ramp.
//
// A real IR designator emits outside the visible band: to the naked eye there is
// nothing there at all, and through an intensifier the beam is a hard white line
// because the tube's phosphor output is monochrome regardless of input
// wavelength. So this draws only while the goggles are up, and draws white
// rather than the red of a visible-light laser.
//
// The line runs from the muzzle to the point the weapon would actually hit,
// found with the same segment cast the shot itself uses. Drawing it from the
// camera instead would be easier and wrong -- the offset between eye and muzzle
// is exactly what makes a laser useful at close range.
static void UpdateIRLaser() {
    scene.irLaser.visible = false;
    const SGE::ResolvedWeaponStats weaponStats =
        scene.player.ResolveWeaponStats(GunModel::SelectedWeapon());
    const bool visibleRailLaser = weaponStats.laserSight;
    // The IR beam fades with the goggle ramp. A visible laser has no such ramp
    // and stays red even when NVG happens to be raised at the same time.
    const float visibility = visibleRailLaser ? 1.0f :
        (std::min)(1.0f, g_nightVisionBlend);
    if (visibility <= 0.01f) return;
    if (!scene.gun.visible || scene.player.health <= 0.0f) return;
    // Thrown and placed equipment has no barrel to bolt a designator to.
    if (GunModel::C4Selected() || GunModel::HarpoonSelected()) return;
    // The scope's own reticle is the aiming reference when glassing; a beam
    // across the lens would only obscure it.
    if (scene.sniperScopeBlend > 0.25f) return;

    // Origin rides the gun; direction comes from the camera. A designator is
    // zeroed to point of aim, so the dot belongs on the crosshair.
    //
    // Casting along the gun's own forward axis instead is the physically
    // literal reading and plays badly: the view model sways hard when strafing,
    // so holding right swung the barrel left and threw the dot metres off the
    // crosshair at any distance. The sway is a view-model flourish, not real
    // weapon movement -- the bullets ignore it too, since spread is centred on
    // the camera axis. Following it would make the laser disagree with both the
    // crosshair and the shot.
    const XMFLOAT3 muzzle = scene.GetMuzzleWorldPosition();
    const XMFLOAT3 origin = scene.camera.Position;
    constexpr float kRange = 260.0f;

    // Carry the weapon's idle sway into the cast direction, so the far end
    // drifts with the same rhythm the muzzle does and the beam translates as one
    // rigid line. Aiming straight down the camera axis instead pinned the far
    // end still while the near end rode the sway, which made the beam pivot
    // about the dot -- the opposite of how a rail-mounted designator behaves.
    //
    // Rotated in the camera's own frame (yaw about its up, pitch about its
    // right) rather than about world axes, so the drift stays consistent when
    // looking up or down. The sway is capped at +/-0.9 degrees, so the dot stays
    // within a whisker of the crosshair at any usable range.
    const XMVECTOR camFront = XMVector3Normalize(
        XMLoadFloat3(&scene.camera.Front));
    const XMVECTOR camUp = XMVector3Normalize(XMLoadFloat3(&scene.camera.Up));
    XMVECTOR camRight = XMVector3Cross(camUp, camFront);
    if (XMVectorGetX(XMVector3LengthSq(camRight)) < 1e-6f)
        camRight = XMVectorSet(1.0f, 0.0f, 0.0f, 0.0f);
    camRight = XMVector3Normalize(camRight);
    const XMMATRIX swayRotation =
        XMMatrixRotationAxis(camUp, XMConvertToRadians(scene.gunSwayYaw)) *
        XMMatrixRotationAxis(camRight, XMConvertToRadians(scene.gunSwayPitch));
    XMFLOAT3 aimDirection;
    XMStoreFloat3(&aimDirection,
        XMVector3Normalize(XMVector3TransformNormal(camFront, swayRotation)));

    const XMFLOAT3 end{ origin.x + aimDirection.x * kRange,
                        origin.y + aimDirection.y * kRange,
                        origin.z + aimDirection.z * kRange };
    XMFLOAT3 target = end;
    float closestDistanceSq = FLT_MAX;
    auto accept = [&](const XMFLOAT3& hit) {
        const float dx = hit.x - origin.x, dy = hit.y - origin.y,
                    dz = hit.z - origin.z;
        const float distanceSq = dx * dx + dy * dy + dz * dz;
        if (distanceSq < closestDistanceSq) {
            closestDistanceSq = distanceSq;
            target = hit;
        }
    };
    XMFLOAT3 hit;
    if (scene.useDestruction && g_destruction.IsInitialized() &&
        g_destruction.HitTestSegment(origin, end, 0.03f, hit)) accept(hit);
    if (HitTerrainSegment(origin, end, 0.03f, hit)) accept(hit);

    // Published for ForwardRenderer to draw as world geometry rather than a HUD
    // overlay, so the depth buffer clips it against the scene.
    //
    // Start a little ahead of the muzzle: the emitter sits within a few
    // centimetres of the near clip plane, and geometry straddling that plane
    // gets sliced open -- the beam would flare into a wedge across the bottom of
    // the screen. Slid along the muzzle-to-target line so it moves down the beam
    // rather than nudging it off-line.
    const XMVECTOR beamDirection = XMVector3Normalize(
        XMLoadFloat3(&target) - XMLoadFloat3(&muzzle));
    XMFLOAT3 beamStart;
    XMStoreFloat3(&beamStart,
                  XMLoadFloat3(&muzzle) + beamDirection * 0.35f);
    scene.irLaser.start = beamStart;
    scene.irLaser.end = target;
    scene.irLaser.color = visibleRailLaser ?
        XMFLOAT3{ 1.0f, 0.025f, 0.012f } : XMFLOAT3{ 1.0f, 1.0f, 1.0f };
    scene.irLaser.visibility = visibility;
    scene.irLaser.visible = true;
}

// Debug beam down the true shot ray, for checking that what a sight shows and
// where the round goes are the same line.
//
// Deliberately NOT the IR designator above. That one starts at the muzzle and
// carries the viewmodel's idle sway, both of which are presentation: it answers
// "where is the gun pointing". This answers "where does the bullet go", which is
// camera.Position along camera.Front with no sway and no muzzle offset, because
// that is the ray ShootBullet spreads around. Keeping them separate is the whole
// point -- if the two beams diverge, the difference is exactly the presentation
// error, which is what makes this useful for aligning an optic.
static void UpdateAimDebugRay() {
    scene.aimDebugRay.visible = false;
    if (!scene.showAimDebugRay) return;
    if (scene.player.health <= 0.0f) return;

    const XMFLOAT3 origin = scene.camera.Position;
    const XMVECTOR camFront = XMVector3Normalize(
        XMLoadFloat3(&scene.camera.Front));
    XMFLOAT3 direction;
    XMStoreFloat3(&direction, camFront);

    const float range = (std::max)(1.0f, scene.aimDebugRayLength);
    const XMFLOAT3 rayEnd{ origin.x + direction.x * range,
                        origin.y + direction.y * range,
                        origin.z + direction.z * range };

    // Stop at the first thing hit, so the dot marks the surface a shot would
    // strike rather than running through it.
    XMFLOAT3 target = rayEnd;
    float closestDistanceSq = FLT_MAX;
    auto accept = [&](const XMFLOAT3& hit) {
        const float dx = hit.x - origin.x, dy = hit.y - origin.y,
                    dz = hit.z - origin.z;
        const float distanceSq = dx * dx + dy * dy + dz * dz;
        if (distanceSq < closestDistanceSq) {
            closestDistanceSq = distanceSq;
            target = hit;
        }
    };
    XMFLOAT3 hit;
    if (scene.useDestruction && g_destruction.IsInitialized() &&
        g_destruction.HitTestSegment(origin, rayEnd, 0.03f, hit)) accept(hit);
    if (HitTerrainSegment(origin, rayEnd, 0.03f, hit)) accept(hit);

    // Pushed off the eye by more than the near plane: a beam starting exactly
    // at the camera straddles it and smears across the screen.
    XMFLOAT3 beamStart;
    XMStoreFloat3(&beamStart, XMLoadFloat3(&origin) + camFront * 0.35f);
    scene.aimDebugRay.start = beamStart;
    scene.aimDebugRay.end = target;
    // Green, so it reads apart from the red rail laser and the white IR beam
    // when more than one is up at once.
    scene.aimDebugRay.color = XMFLOAT3{ 0.10f, 1.0f, 0.20f };
    scene.aimDebugRay.visibility = 1.0f;
    scene.aimDebugRay.visible = true;
}

static void BeginLevelLoading() {
    g_uploadHeapRelease.Reset();
    g_game.loading.Begin({
        g_emptyLevelMode ? 6u : 12u,
        g_emptyLevelMode ? "Terrain material"
                         : "Terrain material and crate model",
        g_emptyLevelMode ? "floor material" : "Content/Models/h2.glb"
    });
    if (!BeginTextureUploadArenaDX12()) {
        g_game.loading.SetCurrent(
            "Unable to begin pooled texture staging",
            "texture upload arena is still owned by an earlier load");
        g_game.loading.Complete(false);
        SGE_LOG("LogRender", EngineLog::Level::Error,
            "Level load aborted: texture upload arena was not idle");
        return;
    }
    levelLoadingUploadBaseline = GetStaticBufferStatsDX12();
}

static void AdvanceLevelLoading(LevelLoadStage next, const char* label,
                                const char* asset, bool succeeded = true) {
    g_game.loading.Advance(next, label, asset, succeeded);
}

static void CompleteLevelLoading(bool succeeded = true) {
    g_game.loading.Complete(succeeded);
}

